apply_to &lt;- function(d, f) {
  browser()
  res &lt;- c()
  for (i in 1:length(d)) {
    res[i] &lt;- f(d[i])
    names(res)[i] &lt;- names(d[i])[1]
  }
  res
}





apply_to &lt;- function(d, f, ...) {
  res &lt;- c()
  dots &lt;- length(dots_list())
  for (i in 1:length(d)) {
    if (dots &gt; 0) res[i] &lt;- f(d[[i]], ...)
    else res[i] &lt;- f(d[[i]])
    names(res)[i] &lt;- names(d[i])[1]
  }
  res
}

fibonacci &lt;- function(n, a, b) {
  if (n==1) return(a)
  if (n == 2) return(b)

  fibonacci(n-1, a, b) + fibonacci(n-2, a, b)
}

fibonacci &lt;- function(n, a, b) {
  if (n==1) return(a)
  if (n == 2) return(b)

  fibonacci(n-1, b, a+b)
}

fibonacci(70, 1L,1L) # overflow of integers
fibonacci(70, 1.0,1.0)

print(fibonacci(70, 1.0,1.0), digits=16)



`+` &lt;- function(x, y) {
  if (all(is.character(x) & is.character(y))) {
    return(paste(x, y, sep=""))
  }
  base::`+`(x, y) # can't write x + y here - calls itself
}
