`+` &lt;- function(left, right) {
  left &lt;- signif(left, p)
  right &lt;- signif(right, p)
  signif(base::`+`(left, right), p)
}

`*` &lt;- function(left, right) {
  left &lt;- signif(left, p)
  right &lt;- signif(right, p)
  signif(base::`*`(left, right), p)
}

