# What is the relative error of the expression x^2 - y^2
# for 𝑥=3.34,𝑦=3.33
f &lt;- function(x, y, p) {
  x &lt;- signif(x, p)
  y &lt;- signif(y, p)

  signif(signif(x^2,p) - signif(y^2, p), p)
}

